#!/usr/bin/env python3
"""Deterministically generate the tiny offline HYG v4.1 subset (CC BY-SA 4.0).
Input is a checked-in pinned-source extraction; no network is used by builds.
"""
import csv
from pathlib import Path
root = Path(__file__).resolve().parents[1]
source = root / 'android/app/src/test/resources/reference/stars/hyg-v41-25stars-raw.csv'
out = root / 'android/app/src/main/java/local/skytrails/app/core/StarCatalogData.kt'
rows = sorted(csv.DictReader(source.open()), key=lambda r: int(r['hip']))
text = '''package local.skytrails.app.core

// Generated by scripts/generate-star-catalog.py; do not hand-edit numeric values.
// HYG v4.1, David Nash / Astronexus, CC BY-SA 4.0. See docs/data/star-catalog.md.
internal val catalogStars = listOf(
'''
text += ',\n'.join(' CatalogStar(%s,%.9f,%s,%s,%s,%s)' %
 (r['hip'], float(r['ra'])*15, r['dec'], r['pmra'], r['pmdec'], r['mag']) for r in rows)
out.write_text(text+'\n)\n')
print(f'{len(rows)} stars, generated {out.stat().st_size} bytes')
